import java.util.Scanner;

public class Main {
    static class Mahsulot {
        String nom;
        long narx;

        Mahsulot(String nom, long narx) {
            this.nom = nom;
            this.narx = narx;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Mahsulot[] ombor = new Mahsulot[n];
        for (int i = 0; i < n; i++) {
            ombor[i] = new Mahsulot(in.next(), in.nextLong());
        }

        int q = in.nextInt();
        for (int j = 0; j < q; j++) {
            String x = in.next();
            long javob = -1;
            for (int i = 0; i < n - 1; i++) {
                if (ombor[i].nom.equals(x)) javob = ombor[i].narx;
            }
            System.out.println(javob);
        }
    }
}

