    int n;
    cin >> n;
    vector<Mahsulot> ombor;
    for (int i = 0; i < n; i++) {
        string nom;
        long long narx;
        cin >> nom >> narx;
        ombor.emplace_back(nom, narx);
    }

    int q;
    cin >> q;
    for (int j = 0; j < q; j++) {
        string x;
        cin >> x;
        long long javob = -1;
        for (int i = 0; i < n - 1; i++) {
            if (ombor[i].nom == x) javob = ombor[i].narx;
        }
        cout << javob << endl;
    }
    return 0;
}

