#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Mahsulot {
public:
    string nom;
    long long narx;

    Mahsulot(string nom, long long narx) : nom(nom), narx(narx) {}
};

int main() {
    int n;
    cin >> n;
    vector<Mahsulot> ombor;
    for (int i = 0; i < n; i++) {
        string nom;
        long long narx;
        cin >> nom >> narx;
        ombor.emplace_back(nom, narx);
    }

    int q;
    cin >> q;
    for (int j = 0; j < q; j++) {
        string x;
        cin >> x;
        long long javob = -1;
        for (const auto& m : ombor) {
            if (m.nom == x) javob = m.narx;
        }
        cout << javob << endl;
    }
    return 0;
}
